import React, { useEffect, useRef, useState } from 'react';
import emailjs from '@emailjs/browser';
import '../components/CSS/Contact.css';
import { showAlert } from '../constants';

// ---- Config (move these to .env, see notes) ----
// CRA:  REACT_APP_EMAILJS_SERVICE_ID=...   -> process.env.REACT_APP_EMAILJS_SERVICE_ID
// Vite: VITE_EMAILJS_SERVICE_ID=...        -> import.meta.env.VITE_EMAILJS_SERVICE_ID
// Fallbacks keep the form working if .env is missing at build time.
// (EmailJS service/template IDs and the public key are not secrets.)
const EMAILJS = {
  serviceId: process.env.REACT_APP_EMAILJS_SERVICE_ID || 'service_x6y1ieo',
  templateId: process.env.REACT_APP_EMAILJS_TEMPLATE_ID || 'template_96z2zkd',
  publicKey: process.env.REACT_APP_EMAILJS_PUBLIC_KEY || 'OFKKIcBP6cJBLJ4x6',
};

const COOLDOWN_MS = 30_000; // block rapid re-sends

const validateField = (name, value) => {
  const v = value.trim();
  if (!v) return 'This field is required';
  if (name === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))
    return 'Please enter a valid email';
  if (name === 'message' && v.length < 10)
    return 'Message must be at least 10 characters';
  return '';
};

const Contact = () => {
  const sectionRef = useRef(null);
  const lastSentRef = useRef(0);

  const [isVisible, setIsVisible] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', message: '' });
  const [honeypot, setHoneypot] = useState(''); // bots fill this, humans never see it
  const [errors, setErrors] = useState({});
  const [touched, setTouched] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Initialise EmailJS once
  useEffect(() => {
    if (EMAILJS.publicKey) emailjs.init(EMAILJS.publicKey);
  }, []);

  // Fade-in once (doesn't flicker on scroll away)
  useEffect(() => {
    const node = sectionRef.current;
    if (!node) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.1, rootMargin: '0px 0px -50px 0px' }
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  const validateForm = () => {
    const newErrors = {};
    Object.entries(formData).forEach(([name, value]) => {
      newErrors[name] = validateField(name, value);
    });
    setErrors(newErrors);
    setTouched({ name: true, email: true, message: true });
    return Object.values(newErrors).every((e) => !e);
  };

  const handleChange = ({ target: { name, value } }) => {
    setFormData((prev) => ({ ...prev, [name]: value }));
    if (touched[name]) {
      setErrors((prev) => ({ ...prev, [name]: validateField(name, value) }));
    }
  };

  const handleBlur = ({ target: { name, value } }) => {
    setTouched((prev) => ({ ...prev, [name]: true }));
    setErrors((prev) => ({ ...prev, [name]: validateField(name, value) }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (isSubmitting) return;

    // Silently drop bot submissions
    if (honeypot) return;

    if (!EMAILJS.serviceId || !EMAILJS.templateId || !EMAILJS.publicKey) {
      console.error('EmailJS env variables are missing.');
      showAlert('error', 'Contact form is not configured. Please email me directly.');
      return;
    }

    if (Date.now() - lastSentRef.current < COOLDOWN_MS) {
      showAlert('error', 'Please wait a few seconds before sending another message.');
      return;
    }

    if (!validateForm()) return;

    setIsSubmitting(true);

    const time = new Date().toLocaleString([], {
      dateStyle: 'medium',
      timeStyle: 'short',
    });

    try {
      await emailjs.send(
        EMAILJS.serviceId,
        EMAILJS.templateId,
        {
          name: formData.name.trim(),
          email: formData.email.trim(),
          message: formData.message.trim(),
          time,
          // aliases so common template variable names all work
          from_name: formData.name.trim(),
          from_email: formData.email.trim(),
          reply_to: formData.email.trim(),
        },
        EMAILJS.publicKey
      );

      lastSentRef.current = Date.now();
      showAlert('success', 'Thank you! Your message has been sent successfully!');
      setFormData({ name: '', email: '', message: '' });
      setTouched({});
      setErrors({});
    } catch (error) {
      // EmailJS rejects with { status, text }
      console.error('EmailJS error:', error?.status, error?.text || error);

      let msg = 'Oops! Something went wrong. Please try again.';
      if (error?.status === 429) msg = 'Too many requests. Please try again later.';
      else if (error?.status === 412 || error?.status === 401 || error?.status === 403)
        msg = 'Email service is temporarily unavailable. Please email me directly.';
      else if (!error?.status)
        msg = 'Network error. Please check your connection and try again.';

      showAlert('error', msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const fields = ['name', 'email', 'message'];

  return (
    <section
      id="contact"
      ref={sectionRef}
      className={`contact section ${isVisible ? 'visible' : ''}`}
      aria-labelledby="contact-heading"
    >
      <div className="section-title">
        <h2 id="contact-heading">Contact Me</h2>
      </div>

      <form
        className="contact-form"
        onSubmit={handleSubmit}
        autoComplete="off"
        noValidate
        style={{ position: 'relative' }}
      >
        {/* Honeypot: hidden from users and screen readers */}
        <input
          type="text"
          name="website"
          tabIndex={-1}
          autoComplete="off"
          aria-hidden="true"
          value={honeypot}
          onChange={(e) => setHoneypot(e.target.value)}
          style={{ position: 'absolute', left: '-9999px', opacity: 0, height: 0, width: 0 }}
        />

        {fields.map((field) => {
          const label = field.charAt(0).toUpperCase() + field.slice(1);
          const hasError = touched[field] && errors[field];
          const common = {
            id: field,
            name: field,
            placeholder: `Your ${label}`,
            value: formData[field],
            onChange: handleChange,
            onBlur: handleBlur,
            className: hasError ? 'error' : '',
            autoComplete: 'off',
            'aria-invalid': hasError ? 'true' : 'false',
            'aria-describedby': hasError ? `${field}-error` : undefined,
          };

          return (
            <div className="form-group" key={field}>
              <label htmlFor={field} className="sr-only">
                {label}
              </label>
              {field === 'message' ? (
                <textarea {...common} rows="5" />
              ) : (
                <input {...common} type={field === 'email' ? 'email' : 'text'} />
              )}
              {hasError && (
                <span id={`${field}-error`} className="error-message" role="alert" style={{ color: 'red' }}>
                  {errors[field]}
                </span>
              )}
            </div>
          );
        })}

        <button
          type="submit"
          className={`contact-btn ${isSubmitting ? 'disabled' : ''}`}
          disabled={isSubmitting}
          aria-disabled={isSubmitting}
        >
          <span className="btn-icon" aria-hidden="true">
            <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor">
              <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
            </svg>
          </span>
          <span className="btn-text">
            {isSubmitting ? (
              <>
                <span className="spinner"></span> Sending...
              </>
            ) : (
              'Send Message'
            )}
          </span>
        </button>
      </form>
    </section>
  );
};

export default Contact;