// Paste this into your constants file in place of the old showAlert.
// Make sure Success.gif and Error.gif live in: public/assets/gifs/

export function showAlert(type, message) {
  const isSuccess = type === 'success';
  const alertType = isSuccess ? 'success' : 'error';

  // Remove any existing alert (and its timer / key listener)
  const existing = document.getElementById('custom-alert');
  if (existing) existing._close?.();

  // PUBLIC_URL makes the path work on GitHub Pages (/MicroStarkDev-PortFolio/...)
  const base = process.env.PUBLIC_URL || '';
  const gifUrl = `${base}/assets/gifs/${isSuccess ? 'Success' : 'Error'}.gif`;

  // Overlay
  const overlay = document.createElement('div');
  overlay.id = 'custom-alert';
  overlay.className = 'custom-alert-overlay';

  // Box
  const box = document.createElement('div');
  box.className = `custom-alert-box ${alertType}`;
  box.setAttribute('role', 'alert');
  box.setAttribute('aria-live', 'assertive');

  // Close button
  const closeBtn = document.createElement('button');
  closeBtn.className = 'custom-alert-close';
  closeBtn.setAttribute('aria-label', 'Close alert');
  closeBtn.textContent = '×';

  // Icon
  const img = document.createElement('img');
  img.className = 'custom-alert-icon';
  img.src = gifUrl;
  img.alt = alertType;
  img.onerror = () => img.remove(); // don't show a broken image if the GIF is missing

  // Text (textContent, not innerHTML, so message can never inject HTML)
  const content = document.createElement('div');
  content.className = 'custom-alert-content';

  const title = document.createElement('p');
  title.className = 'custom-alert-title';
  title.textContent = isSuccess ? 'Success!' : 'Error!';

  const msg = document.createElement('p');
  msg.className = 'custom-alert-message';
  msg.textContent = message;

  content.append(title, msg);
  box.append(closeBtn, img, content);
  overlay.appendChild(box);
  document.body.appendChild(overlay);

  // Close logic (clears timer + key listener)
  let timeoutId;
  const onKeyDown = (e) => {
    if (e.key === 'Escape') close();
  };
  function close() {
    clearTimeout(timeoutId);
    document.removeEventListener('keydown', onKeyDown);
    overlay.remove();
  }
  overlay._close = close;

  closeBtn.addEventListener('click', close);
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) close(); // click outside the box
  });
  document.addEventListener('keydown', onKeyDown);

  // Auto-dismiss after 10 seconds
  timeoutId = setTimeout(close, 10000);
  closeBtn.focus();
}